function addTwoDelayed(first: number[], second: number[]): number[] {
  const pending = [first, second];
  let t = 0, sum = 0, done = 0;
  while (true) {
    for (const [value, delay] of pending) if (delay === t) { sum += value; done++; }
    if (done === pending.length) return [sum, t];
    t++;
  }
}

