class Solution:
    def addTwoDelayed(self, first: List[int], second: List[int]) -> List[int]:
        pending = [first, second]
        t = total = done = 0
        while True:
            for value, delay in pending:
                if delay == t:
                    total += value
                    done += 1
            if done == len(pending):
                return [total, t]
            t += 1

